export type ErasureStatus = 'pending' | 'processing' | 'failed' | 'completed';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: ErasureStatus;
  attempts: number;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
  last_error: string | null;
}

export interface ErasureSubject {
  id: string;
  merchant_id: string;
  external_reference: string;
  email: string;
  name: string;
  phone: string | null;
}

export interface ClaimedErasure extends ErasureRequestRow {
  subject?: ErasureSubject;
}

export interface ErasureResponse {
  id: string;
  customerId: string;
  status: ErasureStatus;
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

export function erasureResponse(row: ErasureRequestRow): ErasureResponse {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at?.toISOString() ?? null,
    lastError: row.last_error,
  };
}

export class ErasureRepository {
  async create(merchantId: string, customerId: string, key: string): Promise<ErasureRequestRow> {
    return await transaction(async (client) => {
      const replay = await client.query<ErasureRequestRow & { keyed_customer_id: string }>(
        `SELECT r.*,r.customer_id keyed_customer_id
         FROM customers.erasure_idempotency_keys k
         JOIN customers.erasure_requests r ON r.id=k.request_id
         WHERE k.merchant_id=$1 AND k.key=$2 FOR UPDATE OF k,r`,
        [merchantId, key],
      );
      if (replay.rows[0]) {
        if (replay.rows[0].keyed_customer_id !== customerId) {
          throw Object.assign(new Error('idempotency_key_conflict'), { statusCode: 409 });
        }
        return replay.rows[0];
      }

      const customer = await client.query(
        `SELECT id FROM customers.customers WHERE merchant_id=$1 AND id=$2 FOR UPDATE`,
        [merchantId, customerId],
      );
      const existing = await client.query<ErasureRequestRow>(
        `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
        [merchantId, customerId],
      );
      if (existing.rows[0]) {
        await this.saveKey(client, merchantId, key, existing.rows[0].id);
        return existing.rows[0];
      }
      if (!customer.rowCount) throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });

      const created = await client.query<ErasureRequestRow>(
        `INSERT INTO customers.erasure_requests(merchant_id,customer_id)
         VALUES($1,$2) RETURNING *`,
        [merchantId, customerId],
      );
      await client.query(
        `UPDATE customers.customers SET status='erasure_pending',version=version+1,updated_at=now()
         WHERE merchant_id=$1 AND id=$2`,
        [merchantId, customerId],
      );
      await this.saveKey(client, merchantId, key, created.rows[0]!.id);
      return created.rows[0]!;
    });
  }

  async find(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async recoverExpiredLeases(): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='failed',available_at=now(),locked_by=NULL,locked_at=NULL,lease_expires_at=NULL,
           last_error='worker_lease_expired',updated_at=now()
       WHERE status='processing' AND lease_expires_at<now()`,
    );
  }

  async claim(workerId: string): Promise<ClaimedErasure | undefined> {
    return await transaction(async (client) => {
      const result = await client.query<ErasureRequestRow>(
        `UPDATE customers.erasure_requests
         SET status='processing',attempts=attempts+1,locked_by=$1,locked_at=now(),
             lease_expires_at=now()+interval '5 minutes',last_error=NULL,updated_at=now()
         WHERE id=(SELECT id FROM customers.erasure_requests
           WHERE status IN ('pending','failed') AND available_at<=now()
           ORDER BY available_at,created_at FOR UPDATE SKIP LOCKED LIMIT 1)
         RETURNING *`,
        [workerId],
      );
      const request = result.rows[0];
      if (!request) return undefined;
      const subject = await client.query<ErasureSubject>(
        `SELECT id,merchant_id,external_reference,email,name,phone
         FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
        [request.merchant_id, request.customer_id],
      );
      return { ...request, subject: subject.rows[0] };
    });
  }

  async documentKeys(merchantId: string, customerId: string): Promise<string[]> {
    const result = await pool.query<{ object_key: string }>(
