{"command":"create","path":"/workspace/source/apps/customer-service/src/erasure-service.ts","file_text":"import { createHash, randomUUID } from 'node:crypto';
import { Redis } from 'ioredis';
import { config } from '../../../packages/config/src/index.js';
import { deleteMailpitMessagesForRecipient } from '../../../packages/notifications/src/mailpit.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import { logger } from '../../../packages/observability/src/logger.js';
import {
  ErasureRepository,
  erasureResponse,
  type ClaimedErasure,
  type ErasureRequestRow,
  type ErasureResponse,
} from './erasure-repository.js';

const redis = new Redis(config().REDIS_URL, { lazyConnect: true });

export class ErasureService {
  constructor(private readonly repository = new ErasureRepository()) {}

  async request(merchantId: string, customerId: string, key: string): Promise<ErasureResponse> {
    return erasureResponse(await this.repository.create(merchantId, customerId, key));
  }

  async find(merchantId: string, requestId: string): Promise<ErasureResponse | undefined> {
    const request = await this.repository.find(merchantId, requestId);
    return request ? erasureResponse(request) : undefined;
  }

  async process(request: ClaimedErasure): Promise<void> {
    try {
      const documentKeys = await this.repository.documentKeys(request.merchant_id, request.customer_id);
      await this.repository.scrubDatabase(request, false);
      await this.removeDocuments(documentKeys);
      await this.removeSearchAndCache(request);
      if (request.subject) await deleteMailpitMessagesForRecipient(request.subject.email);
      await this.repository.scrubDatabase(request, true);
    } catch (error) {
      logger.warn({ requestId: request.id, error }, 'customer erasure attempt failed');
      await this.repository.fail(request, 'cleanup_failed');
    }
  }

  async stop(): Promise<void> {
    if (redis.status !== 'wait') await redis.quit();
  }

  private async removeDocuments(keys: string[]): Promise<void> {
    for (const key of keys) await objectStore.removeObject(DOCUMENT_BUCKET, key);
  }

  private async removeSearchAndCache(request: ClaimedErasure): Promise<void> {
    const id = `${request.merchant_id}:${request.customer_id}`;
    try {
      await searchClient.delete({ index: CUSTOMER_INDEX, id, refresh: true });
    } catch (error) {
      const statusCode = (error as { meta?: { statusCode?: number } }).meta?.statusCode;
      if (statusCode !== 404) throw error;
    }
    if (redis.status === 'wait') await redis.connect();
    const key = `merchant:${request.merchant_id}:customer:${request.customer_id}`;
    await redis.del(key, `${key}:activity`);
  }
}

export async function runErasureWorker(signal: AbortSignal): Promise<void> {
  const service = new ErasureService();
  const repository = new ErasureRepository();
  const workerId = `customer-erasure-${randomUUID()}`;
  let lastRecovery = 0;
  while (!signal.aborted) {
    if (Date.now() - lastRecovery > 30_000) {
      await repository.recoverExpiredLeases();
      lastRecovery = Date.now();
    }
    const request = await repository.claim(workerId);
    if (!request) {
      await new Promise((resolve) => setTimeout(resolve, 250));
      continue;
    }
    await service.process(request);
  }
  await service.stop();
}

export function erasureRequestFingerprint(row: ErasureRequestRow): string {
  return createHash('sha256').update(`${row.merchant_id}:${row.customer_id}`).digest('hex');
}
